using System.IO.Compression;
using System.Text.Json;
using EqlTracker.Core;

internal static class AdvancedTrackerTests
{
    private static readonly DateTime Start = new(2026, 10, 14, 18, 0, 0, DateTimeKind.Local);
    private static ParsedLine Parse(string message, double seconds = 0) => new LogParser("ExampleHero").Parse($"[{Start.AddSeconds(seconds):ddd MMM dd HH:mm:ss yyyy}] {message}", Guid.NewGuid().ToString())!;
    private static void Check(bool value, string message = "Assertion failed") { if (!value) throw new Exception(message); }
    private static void Equal<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"Expected {expected}, got {actual}"); }
    private static CombatEngine Group(out CharacterProfile profile)
    { profile = new(); var engine = new CombatEngine(profile); engine.Process(Parse("You have joined the group.")); engine.Process(Parse("Krasus has joined the group.")); return engine; }
    private static (CharacterProfile Profile, CombatEngine Engine) Summon(string spell, string name = "Cloudling")
    { var p = new CharacterProfile(); var e = new CombatEngine(p); e.Process(Parse("You begin casting " + spell + ".")); e.Process(Parse(name + " begins casting Skin like Steel.", 6)); e.Process(Parse(name + " told you, 'Attacking a large rat Master.'", 42)); return (p, e); }
    private static Encounter Fight() => new()
    {
        Start = Start, End = Start.AddSeconds(10), PlayerDamage = 50, PetDamage = 250,
        Events = [new() { Time = Start, Actor = "Cloudling", Owner = "Pet", Target = "a rat", Ability = "slashes", Damage = 100 }, new() { Time = Start.AddSeconds(3), Actor = "Cloudling", Owner = "Pet", Target = "a rat", Ability = "slashes", Damage = 100, Critical = true }, new() { Time = Start.AddSeconds(5), Actor = "Cloudling", Owner = "Pet", Target = "a bat", Ability = "Frost Strike", Kind = "Spell", DamageType = "cold", Damage = 50 }, new() { Time = Start.AddSeconds(10), Actor = "ExampleHero", Owner = "Player", Target = "a bat", Ability = "slashes", Damage = 50 }]
    };
    private static string Temp() { string path = Path.Combine(Path.GetTempPath(), "EQL-advanced-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(path); return path; }
    public static void Register(Action<string, Action> test)
    {
        test("Live game settings reader tolerates exclusive client locks and recovers", () => { string path = Path.Combine(Temp(), "eqclient.ini"); File.WriteAllText(path, "[VideoMode]\nFullscreen=0\n"); using (var held = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, FileShare.None)) Check(!GameSettingsReader.TryReadText(path, out _)); Check(GameSettingsReader.TryReadText(path, out string text)); Check(text.Contains("Fullscreen=0")); });
        test("Live game settings reader shares normal client writes", () => { string path = Path.Combine(Temp(), "UI.ini"); File.WriteAllText(path, "UISkin=Rune4K_Frost_Clear\n"); using var held = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, FileShare.ReadWrite | FileShare.Delete); Check(GameSettingsReader.TryReadText(path, out string text)); Check(text.Contains("Rune4K_Frost_Clear")); });
        test("Missing or empty game settings leave cached values available", () => { string path = Path.Combine(Temp(), "UI.ini"); Check(!GameSettingsReader.TryReadText(path, out _)); File.WriteAllText(path, ""); Check(!GameSettingsReader.TryReadText(path, out _)); });
        test("Confirmed group attacks maintain resumable encounter without credited damage", () =>
        {
            var engine = Group(out var p); engine.Process(Parse("You slash a rat for 100 points of damage.", 1));
            engine.Process(Parse("Krasus slashes a bat for 900 points of damage.", 8)); engine.Process(Parse("Krasus tries to slash a bat, but misses!", 15)); engine.Tick(Start.AddSeconds(22)); Check(engine.Current != null);
            Equal(100L, engine.Current!.Damage); Equal(14d, engine.Current.Duration); Equal(2, engine.Current.Events.Count(x => x.ActivityOnly)); Equal(100L, CombatMetrics.Breakdown([engine.Current], new()).Sum(x => x.Damage)); Check(p.GroupRosterIncomplete); engine.Tick(Start.AddSeconds(46)); Equal(1, engine.Encounters.Count);
        });
        test("Incoming attacks against confirmed group members maintain activity", () => { var engine = Group(out _); engine.Process(Parse("You slash a rat for 10 points of damage.", 1)); engine.Process(Parse("a bat bites Krasus for 80 points of damage.", 8)); Equal(7d, engine.Current!.Duration); Equal(10L, engine.Current.Damage); Check(engine.Current.Events.Last().ActivityOnly); });
        test("Manual group pets maintain activity without contributing to personal totals", () => { var p = new CharacterProfile { GroupMembers = [new() { Name = "Fluffy", IsPet = true, Source = "Manual", From = Start }] }; var e = new CombatEngine(p); e.Process(Parse("Fluffy slashes a rat for 90 points of damage.")); Equal(0L, e.Current!.Damage); Equal("Group", e.Current.Events.Single().Owner); });
        test("Nearby attacks on an engaged target never extend the idle timer", () => { var e = new CombatEngine(new()); e.Process(Parse("You slash a rat for 100 points of damage.")); e.Process(Parse("Stranger slashes a rat for 700 points of damage.", 7)); Equal(Start, e.Current!.End); e.Tick(Start.AddSeconds(31)); Equal(1, e.Encounters.Count); Equal(1d, e.Encounters[0].Duration); });
        test("Unrelated nearby combat cannot start or maintain an encounter", () => { var e = new CombatEngine(new()); e.Process(Parse("Stranger slashes a bat for 700 points of damage.")); Check(e.Current == null); e.Process(Parse("You slash a rat for 1 points of damage.", 1)); e.Process(Parse("Stranger slashes a bat for 700 points of damage.", 7)); Equal(Start.AddSeconds(1), e.Current!.End); });
        test("Group leave and disband close membership intervals", () => { var e = Group(out var p); e.Process(Parse("Krasus has left the group.", 2)); Check(!p.GroupMembers.Single().Contains("Krasus", Start.AddSeconds(3))); e.Process(Parse("Krasus has joined the group.", 4)); e.Process(Parse("Your group has been disbanded.", 5)); Check(!p.InGroup); Check(p.GroupMembers.All(x => x.Until.HasValue)); });
        test("Login clears stale group membership and marks roster coverage unknown", () => { var e = Group(out var p); e.Process(Parse("Welcome to EverQuest Legends!", 20)); Check(!p.InGroup && p.GroupRosterIncomplete); Check(p.GroupMembers.All(x => x.Until == Start.AddSeconds(20))); e.Process(Parse("Krasus slashes a rat for 900 points of damage.", 21)); Check(e.Current == null); });
        test("Who output is not treated as a group roster", () => { var p = new CharacterProfile(); var e = new CombatEngine(p); e.Process(Parse("[50 WAR/CLR/SHM] Krasus (Human)")); Equal(0, p.GroupMembers.Count); });
        test("Five-second rolling DPS respects shared actor and target filters", () => { var engine = Group(out _); engine.Process(Parse("You slash a rat for 100 points of damage.", 2)); engine.Process(Parse("You slash a bat for 50 points of damage.", 3)); engine.Process(Parse("Krasus slashes a rat for 900 points of damage.", 4)); Equal(20d, engine.RollingDps(new CombatFilter("Combined", "a rat"), Start.AddSeconds(5))); Equal(30d, engine.RollingDps(new CombatFilter("Combined"), Start.AddSeconds(5))); });
        test("Group evidence and activity survive SQLite restart", () => { string dir = Temp(); var e = Group(out var p); e.Process(Parse("Krasus slashes a rat for 900 points of damage.", 3)); using (var store = new TrackerStore(Path.Combine(dir, "t.db"))) store.Commit(new(), p, new(), [], e.Current, []); using var restored = new TrackerStore(Path.Combine(dir, "t.db")); Equal("Krasus", restored.Get<CharacterProfile>("profile")!.GroupMembers.Single().Name); Check(restored.Get<Encounter>("liveEncounter")!.Damage == 0); });

        foreach (string element in PetElementDetector.Elements)
        foreach (string tier in new[] { "Conjuration: ", "Greater Conjuration: ", "Greater Summoning: " })
        { string spell = tier + element + " X"; test("Summon element tier/rank: " + spell, () => { var (p, _) = Summon(spell); Equal(element, p.EffectivePetElement); Equal("Correlated summon", p.PetIdentities.Single().ElementConfidence); }); }
        test("Wind alias resolves to Air", () => Equal("Air", PetElementDetector.SummonElement("Greater Conjuration: Wind IV")));
        test("Interrupted elemental summon is rejected", () => { var p = new CharacterProfile(); var e = new CombatEngine(p); e.Process(Parse("You begin casting Greater Conjuration: Earth X.")); e.Process(Parse("Your Greater Conjuration: Earth X spell is interrupted.", 4)); e.Process(Parse("Cloudling told you, 'Attacking a rat Master.'", 8)); Equal("Unknown", p.EffectivePetElement); });
        test("Fizzled elemental summon is rejected", () => { var p = new CharacterProfile(); var e = new CombatEngine(p); e.Process(Parse("You begin casting Conjuration: Fire.")); e.Process(Parse("Your Conjuration: Fire spell fizzles!", 1)); e.Process(Parse("Cloudling told you, 'Attacking a rat Master.'", 8)); Equal("Unknown", p.EffectivePetElement); });
        test("Summon failure invalidates already correlated activity", () => { var (p, e) = Summon("Conjuration: Earth"); e.Process(Parse("Your Conjuration: Earth spell is interrupted.", 10)); Equal("Unknown", p.EffectivePetElement); });
        test("Unrelated buff interruption does not reject successful summon", () => { var (p, e) = Summon("Conjuration: Earth"); e.Process(Parse("You begin casting Burnout III I.", 7)); e.Process(Parse("Your Burnout III I spell is interrupted.", 10)); Equal("Earth", p.EffectivePetElement); });
        test("Legacy Water loadout default is not confirmed elemental evidence", () => { var p = new CharacterProfile { Loadouts = [new() { PetType = "Water" }] }; Equal("Water", p.ActiveLoadout.PetType); Equal("Unknown", p.EffectivePetElement); });
        test("Manual elemental override wins over correlated summon", () => { var (p, _) = Summon("Conjuration: Earth"); p.PetElementOverride = "Fire"; Equal("Fire", p.EffectivePetElement); p.PetElementOverride = ""; Equal("Earth", p.EffectivePetElement); });
        test("Pet death removes active element and replacement gets new evidence", () => { var (p, e) = Summon("Conjuration: Earth"); e.Process(Parse("Cloudling has been slain by a rat!", 43)); Equal("Unknown", p.EffectivePetElement); e.Process(Parse("You begin casting Conjuration: Air.", 45)); e.Process(Parse("Jobeker told you, 'Attacking a rat Master.'", 52)); Equal("Air", p.EffectivePetElement); Equal(2, p.PetIdentities.Count); });
        test("Delayed ownership uses earlier post-summon pet activity", () => { var p = new CharacterProfile(); var e = new CombatEngine(p); e.Process(Parse("You begin casting Conjuration: Water.")); e.Process(Parse("Cloudling begins casting Sneak.", 6)); e.Process(Parse("Cloudling told you, 'Attacking a rat Master.'", 180)); Equal("Water", p.EffectivePetElement); });
        test("Signatures remain explicitly inferred and conflicts become unknown", () => { var p = new CharacterProfile(); var e = new CombatEngine(p); e.Process(Parse("Cloudling told you, 'Attacking a rat Master.'")); e.Process(Parse("Cloudling backstabs a rat for 10 points of damage.", 1)); Equal("Water", p.EffectivePetElement); Equal("Inferred", p.PetIdentities.Single().ElementConfidence); e.Process(Parse("Cloudling begins casting Skin like Steel.", 2)); e.Process(Parse("Cloudling begins casting Shield of Brambles.", 3)); Equal("Unknown", p.EffectivePetElement); Equal("Conflicting signatures", p.PetIdentities.Single().ElementConfidence); });
        test("Correlated summon takes precedence over cross-class spell signatures", () => { var (p, e) = Summon("Conjuration: Earth"); e.Process(Parse("Cloudling backstabs a rat for 10 points of damage.", 43)); Equal("Earth", p.EffectivePetElement); Equal("Correlated summon", p.PetIdentities.Single().ElementConfidence); });
        test("Synthetic summon sequence backfills Earth evidence", () => { var p = new CharacterProfile { PetIdentities = [new() { Name = "Cloudling", From = new(2026, 1, 6, 12, 0, 42), Confirmed = false }] }; var detector = new PetElementDetector(); foreach (string text in File.ReadLines(Path.Combine(AppContext.BaseDirectory, "fixtures", "summon-earth.txt"))) detector.Process(new LogParser("ExampleHero").Parse(text)!, p); Equal("Earth", p.EffectivePetElement); Check(p.PetIdentities[0].ElementEvidence.Contains("Greater Conjuration: Earth X")); });

        test("Target and ability breakdowns reconcile with one shared denominator", () => { var f = Fight(); var v = DpsViews.Build([f], null, Start, new() { Actor = "Combined" }); Equal(300L, v.Damage); Equal(300L, v.Rows.Sum(x => x.Damage)); Equal(300L, v.Targets.Sum(x => x.Damage)); Equal(30d, v.Targets.Sum(x => x.Dps)); Equal(100d, v.Targets.Sum(x => x.Percent)); });
        test("Peak hit ties select earliest timestamp", () => { var f = Fight(); var peak = CombatMetrics.Peaks([f], new("Pet")).Single(x => x.Ability == "slashes"); Equal(100L, peak.Damage); Equal(Start, peak.Time); Equal(Start, CombatMetrics.Breakdown([f], new("Pet")).Single(x => x.Ability == "slashes").PeakTime!.Value); });
        test("Peak hit respects target, crit and time filters", () => { var f = Fight(); var filtered = new CombatFilter("Pet", "a rat", CriticalOnly: true, From: Start.AddSeconds(2)); var peak = CombatMetrics.Peaks([f], filtered).Single(); Equal(Start.AddSeconds(3), peak.Time); Equal(100L, CombatMetrics.Targets([f], filtered).Single().Damage); Equal(12.5, CombatMetrics.Breakdown([f], filtered).Single().Dps); });
        test("Session peak hit spans selected encounters", () => { var f = Fight(); var next = Fight(); next.Start = Start.AddSeconds(20); next.End = Start.AddSeconds(25); next.Events = [new() { Owner = "Pet", Actor = "Cloudling", Target = "a rat", Ability = "slashes", Damage = 200, Time = next.End }]; var v = DpsViews.Build([f, next], null, Start, new() { Scope = "Session", Actor = "Pet" }); Equal(200L, v.Peaks.Single(x => x.Ability == "slashes").Damage); });
        test("Summary peaks persist but missing detail is never invented", () => { var f = Fight(); f.Peaks = CombatMetrics.Peaks([f], new()); f.Events.Clear(); f.DetailAvailable = false; var v = DpsViews.Build([f], null, Start, new()); Check(!v.DetailComplete); Check(v.Peaks.Count > 0); Equal(0, v.Rows.Count); f.Peaks.Clear(); Equal(0, DpsViews.Build([f], null, Start, new()).Peaks.Count); });
        test("Damage channel glyph metadata preserves physical and spell schools", () => { var f = Fight(); var rows = CombatMetrics.Breakdown([f], new()); Equal("Physical", rows.Single(x => x.Kind == "Melee").Channel); Equal("Cold", rows.Single(x => x.Kind == "Spell").Channel); foreach (string channel in new[] { "magic", "fire", "poison", "disease", "corruption" }) Check(DamageChannels.From(new() { Kind = "Spell", DamageType = channel }).Equals(channel, StringComparison.OrdinalIgnoreCase)); });
        test("Active export freezes without ending combat and excludes chat", () => { var p = new CharacterProfile(); var f = Fight(); var view = DpsViews.Build([], f, Start, new() { Actor = "Combined" }); var document = EncounterExporter.Snapshot(view, p); f.Events[0].Damage = 999; Equal(100L, document.Encounters[0].Events[0].Damage); Check(!f.Finished); string path = Path.Combine(Temp(), "encounter.zip"); EncounterExporter.Write(path, document); using var zip = ZipFile.OpenRead(path); Equal(11, zip.Entries.Count); foreach (string name in new[] { "summary.csv", "abilities.csv", "targets.csv", "events.csv", "encounters.json", "README.txt" }) Check(zip.GetEntry(name) != null); using var reader = new StreamReader(zip.GetEntry("encounters.json")!.Open()); var json = JsonSerializer.Deserialize<EncounterExportDocument>(reader.ReadToEnd(), Json.Options)!; Equal(300L, json.Damage); Equal(json.Damage, json.Abilities.Sum(x => x.Damage)); Equal(json.Damage, json.Targets.Sum(x => x.Damage)); Check(!json.Encounters[0].Finished); });
        test("Export filters reconcile CSV, JSON and activity evidence", () => { var f = Fight(); f.Events.Add(new() { Owner = "Group", Actor = "Krasus", Target = "a rat", Damage = 900, ActivityOnly = true, Relevance = "Group", Time = Start.AddSeconds(6) }); var p = new CharacterProfile { Meter = new() { Actor = "Pet", Target = "a rat" } }; var doc = EncounterExporter.Snapshot(DpsViews.Build([f], null, Start, p.Meter), p); Equal(200L, doc.Damage); Equal(20d, doc.Dps); Equal(200L, doc.Abilities.Sum(x => x.Damage)); Equal(200L, doc.Targets.Sum(x => x.Damage)); string path = Path.Combine(Temp(), "filtered.zip"); EncounterExporter.Write(path, doc); using var zip = ZipFile.OpenRead(path); using var reader = new StreamReader(zip.GetEntry("events.csv")!.Open()); string csv = reader.ReadToEnd(); Check(csv.Contains("\"Group\"")); Check(csv.Contains("\"True\",\"Group\",\"False\"")); });
        test("Summary-only export explicitly marks missing filtered damage", () => { var f = Fight(); f.DetailAvailable = false; f.Events.Clear(); var p = new CharacterProfile { Meter = new() { Target = "a rat", Actor = "Pet" } }; var doc = EncounterExporter.Snapshot(DpsViews.Build([f], null, Start, p.Meter), p); Check(!doc.DetailComplete); Equal(0, doc.Abilities.Count); Equal(0, doc.PeakHits.Count); string path = Path.Combine(Temp(), "summary.zip"); EncounterExporter.Write(path, doc); using var zip = ZipFile.OpenRead(path); using var reader = new StreamReader(zip.GetEntry("summary.csv")!.Open()); Check(reader.ReadToEnd().Contains("\"\",\"\",\"Summary only\"")); });

        test("Classic acquisition stays collectable for Kunark quest goals through Velious", () => { var catalog = Json.Read<Catalog>(Path.Combine(AppContext.BaseDirectory, "data", "catalog.json")); var p = new CharacterProfile { CurrentClasses = ["WAR"], CurrentExpansion = "Classic", PlanThrough = "Velious" }; var rows = QuestPlanner.Plan(catalog, p, new()); Check(rows.Any(x => x.Item == "Heart of Frost" && QuestPlanner.InZone(x, "Permafrost", "Classic"))); p.PlanThrough = "Classic"; Equal(0, QuestPlanner.Plan(catalog, p, new()).Count); p.Wishlist.Add(new() { Name = "Custom armor", Zone = "Permafrost" }); Equal(1, QuestPlanner.Plan(catalog, p, new()).Count); });
        test("Expansion availability keeps legacy Later unknown", () => { Check(ExpansionRules.Available("Classic", "Kunark")); Check(ExpansionRules.Available("Velious", "Velious")); Check(!ExpansionRules.Available("Velious", "Kunark")); Check(!ExpansionRules.Available("Later", "Velious")); Equal("Classic", ExpansionRules.Current(new())); Equal("Kunark", ExpansionRules.Current(new() { Era = "Kunark" })); });
        test("Zone abbreviation never changes matching", () => { Equal("E. Freeport", ExpansionRules.ShortZone("East Freeport", 240)); Equal("EFP", ExpansionRules.ShortZone("East Freeport", 128)); Equal("east freeport", Identity.ZoneKey("East Freeport")); });

        test("Borderless package applies only display keys and restores reversibly", () => { string game = Temp(), package = Path.Combine(Temp(), "setup"); string path = Path.Combine(game, "eqclient.ini"); File.WriteAllText(path, "[Defaults]\r\nMaximized=0\r\nUIScale=5\r\n[VideoMode]\r\nFullscreen=1\r\nWindowedWidth=1920\r\nWindowedHeight=1080\r\nFullscreenRefreshRate=120\r\n"); BorderlessSetup.Prepare(game, package, 3840, 2160); BorderlessSetup.Apply(package, running: () => false); string applied = File.ReadAllText(path); Check(applied.Contains("Fullscreen=0")); Check(applied.Contains("WindowedWidth=3840")); Check(applied.Contains("FullscreenRefreshRate=120")); Check(applied.Contains("UIScale=5")); File.AppendAllText(path, "Unrelated=77\r\n"); BorderlessSetup.Apply(package, true, () => false); string restored = File.ReadAllText(path); Check(restored.Contains("Fullscreen=1")); Check(restored.Contains("WindowedWidth=1920")); Check(restored.Contains("Unrelated=77")); Check(Directory.EnumerateDirectories(Path.Combine(package, "applied-backups")).Count() == 2); });
        test("Borderless refuses modification while game runs", () => { string game = Temp(), package = Path.Combine(Temp(), "setup"); string path = Path.Combine(game, "eqclient.ini"); File.WriteAllText(path, "[VideoMode]\nFullscreen=1\n"); BorderlessSetup.Prepare(game, package, 3840, 2160); byte[] original = File.ReadAllBytes(path); try { BorderlessSetup.Apply(package, running: () => true); throw new Exception("Accepted running game"); } catch (InvalidOperationException) { } Check(original.SequenceEqual(File.ReadAllBytes(path))); });
        test("Borderless rejects edited managed fields before writes", () => { string game = Temp(), package = Path.Combine(Temp(), "setup"); string path = Path.Combine(game, "eqclient.ini"); File.WriteAllText(path, "[VideoMode]\nFullscreen=1\nWindowedWidth=1920\n"); BorderlessSetup.Prepare(game, package, 3840, 2160); File.AppendAllText(path, "WindowedWidth=2000\n"); byte[] original = File.ReadAllBytes(path); try { BorderlessSetup.Apply(package, running: () => false); throw new Exception("Accepted conflicting fields"); } catch (InvalidOperationException) { } Check(original.SequenceEqual(File.ReadAllBytes(path))); });
    }
}
